int main(void) {
    int rec[4] = {38, 61, 44, 56};
    int target = 50;
    int best = 0;
    int bestdiff = 1000;
    int d, i;
    for (i = 0; i < 4; i++) {
        // 목표와의 거리는 큰 쪽에서 작은 쪽을 빼요.
