#include <stdio.h>

int main(void) {
    int box[6] = {12, 25, 31, 47, 58};
    int n = 5;
    int value = 30;
    int pos = 0;
    int i;
    // value보다 작은 칸을 지나 들어갈 자리 pos를 찾아요.
    while (pos < n && box[pos] < value) {
        pos++;
    }
    // pos부터 뒤의 값들을 한 칸씩 오른쪽으로 밀어요.
    for (i = pos; i < n; i++) {
        box[i + 1] = box[i];
    }
    box[pos] = value;
    n++;
    for (i = 0; i < n; i++) {
        printf("%d ", box[i]);
    }
    return 0;
}

