int main(void) {
    int data[7] = {3, 8, 5, 6, 2, 1, 4};
    int st[7];
    int top = -1;
    int i;
    for (i = 0; i < 7; i++) {
        // 짝수는 쌓고, 홀수가 오면 쌓인 것이 있을 때 하나 꺼내요.
